<template><view class="person-card" :class="{featured}"><view class="person-card-art"><PersonPortrait :person-id="person.id" :name="person.name"/><text class="card-index">人物档案 / {{String(index+1).padStart(2,'0')}}</text></view><view class="person-card-body"><text class="eyebrow">{{person.province==='待核'?'出生地域未载':person.province+' · '+(person.regionBasis||'出生地域')}}</text><view class="card-title-row"><text class="person-card-name">{{person.name}}</text><text class="card-seal">循迹</text></view><text v-if="person.aliases?.length" class="alias">{{person.aliases.join(' / ')}}</text><text class="card-bio">{{person.bio}}</text><view class="card-foot"><button class="card-read" :aria-label="'阅读'+person.name+'档案'" @tap="go('person',{id:person.id})">阅读档案 <text>↗</text></button><button v-if="challengeGroup(person.id)" class="card-learn" @tap="go('learning',{group:challengeGroup(person.id)})">学习挑战</button></view></view></view></template>
<script setup>import PersonPortrait from './PersonPortrait.vue';import {challengeGroup} from '../lib/learning.js';import {go} from '../lib/navigation.js';defineProps({person:Object,index:{default:0},featured:Boolean})</script>
